class PresenceWS {
  constructor(url) { this.url = url; this.ws = null; this.reconnect = true; }
  connect(onMessage) { /* connect and call onMessage({channelId, userId, status, ts}) */ }
  close() { this.reconnect = false; this.ws?.close(); }
